using System;using System.IO;using System.Linq;using System.Collections.Generic;using System.Threading;using System.Web.Script.Serialization;using ReplierDesktop;
public static class SceneJudgeActualChecks {
 public static int Main(string[] args){try{string root=args[0];var json=new JavaScriptSerializer();var content=new ContentStore(Path.Combine(root,"extension/data/replier/content")).Load("dXWu3pyxmSU");var video=new Video{Id=content.VideoId,Title="200렙 찍자마자 750만원 혼줌작 때려서 만든 미친매물 ㅋㅋㅋㅋㅋㅋㅋ"};
 var text=new[]{"정말 떴어 축하야 진짜 놀라네요 ㅋㅋ","편집자님이 직접 털어 지원하신 돈으로 17 순위까지 올라갔는데 보상이 아이스크림 수준이라니 진짜 미친 게임이네요.","잘 뜬 건 맞는데 쓴 돈 생각하면 마냥 웃기도 어렵네요 ㅋㅋ","잘 나와도 아쉬운 마음 드는 게 뭔지 알 것 같네요"};
 var comments=text.Select(t=>new CommentSuggestion{Text=t}).ToArray();var results=new List<List<FitAssessment>>();foreach(string name in DualCommentService.Models)using(var model=new LocalModel(Path.Combine(root,"extension/.runtime/replier-llm"),name)){var assessed=new SceneFitScoring(model,model.Chat).Assess(video,content,comments,CancellationToken.None).GetAwaiter().GetResult();results.Add(assessed);foreach(var r in assessed)Console.WriteLine(name+" | "+r.Eligible+" | "+text[r.Id]+" | "+r.Reason.Split('\n')[0]);model.Unload().GetAwaiter().GetResult();}
 var records=text.Select((t,i)=>new{text=t,expected=i>=2,approved=results.All(r=>r[i].Eligible),gemma=results[0][i],qwen=results[1][i]}).ToArray();File.WriteAllText(Path.Combine(root,"extension/data/replier-grounded-checks/scene-judge-challenges.json"),json.Serialize(records));if(records.Any(r=>r.approved!=r.expected))throw new Exception("Reviewed regression judgment mismatch");Console.WriteLine("PASS reported bad wording and invented summary rejected; two actual-context viewer reactions accepted");return 0;
 }catch(Exception e){Console.Error.WriteLine(e);return 1;}}
}
